import { useEffect, useLayoutEffect, useRef, useState, type ReactNode } from 'react'
import CaseStudyNavbar from '../../components/CaseStudyNavbar'
import DynamicIsland from '../../components/DynamicIsland'
import mockupFrame from '../../assets/shuttle/Mockup/mockup.svg'
import HeroShadow from '../../assets/shuttle/HeroShadow.png'
import { SplashScreen, SearchScreen } from './screens'
import HomeScreen from './screens/HomeScreen'
import KNUSTCrest from '../../assets/shuttle/schools//knust.svg'
import UGCrest from '../../assets/shuttle/schools/Leg.svg'
import UCCCrest from '../../assets/shuttle/schools/ucc.svg'
import MessagesPage from '../messages/MessagesPage'
import FlowSection from './FlowSection'
import DesignSection, { type DesignEntryPoint } from './DesignSection'
import EngineeringSection from './EngineeringSection'


type Tab = 'product' | 'design' | 'engineering'
type TabLanding = 'top' | 'flow' | 'end'

// ── Phone mockup ──────────────────────────────────────────────────────────────

// 'tapping' = shuttle icon is being pressed; white overlay sweeps before splash
type AppState = 'home' | 'tapping' | 'splash' | 'search'

// Interactive home screen — tapping=true plays the launch animation
function PhoneHomeScreen({ tapping }: { tapping?: boolean }) {
  return (
    <div className="shuttle-screen" style={{ overflow: 'hidden' }}>
      <HomeScreen shuttleTapping={tapping} />
    </div>
  )
}

function PhoneMockup({ appState }: { appState: AppState }) {
  return (
    <div className="cs-phone">
      <img className="cs-phone__frame" src={mockupFrame} alt="" aria-hidden="true" />
      <div className="cs-phone__screen">
        <div className="cs-phone__screen-inner">
          {(appState === 'home' || appState === 'tapping') && <PhoneHomeScreen tapping={appState === 'tapping'} />}
          {appState === 'splash' && <SplashScreen />}
          {appState === 'search' && <SearchScreen />}
        </div>
      </div>
    </div>
  )
}

