// ── Scroll-animated product view ──────────────────────────────────────────────

function ProductView() {
  const stageRef = useRef<HTMLDivElement | null>(null)
  const pillRef = useRef<HTMLDivElement | null>(null)
  const itemRefs = useRef<(HTMLDivElement | null)[]>([])
  const appStateRef = useRef<AppState>('home')

  const [appState, setAppState] = useState<AppState>('home')
  const [featIndex, setFeatIndex] = useState(-1)
  const [featProgress, setFeatProgress] = useState(0)

  // Move sliding pill to the active feature item after each render
  useLayoutEffect(() => {
    const pill = pillRef.current
    const item = featIndex >= 0 ? itemRefs.current[featIndex] : null
    if (!pill) return
    if (!item) { pill.style.opacity = '0'; return }
    pill.style.opacity = '1'
    pill.style.top = `${item.offsetTop}px`
    pill.style.height = `${item.offsetHeight}px`
  }, [featIndex])

  // Tapping → splash: wait for the icon-bounce + white overlay (700 ms)
  useEffect(() => {
    if (appState !== 'tapping') return
    const t = setTimeout(() => {
      appStateRef.current = 'splash'
      setAppState('splash')
    }, 700)
    return () => clearTimeout(t)
  }, [appState])

  // Splash → search auto-transition after ~5 s animation completes
  useEffect(() => {
    if (appState !== 'splash') return
    const t = setTimeout(() => {
      appStateRef.current = 'search'
      setAppState('search')
    }, 5000)
    return () => clearTimeout(t)
  }, [appState])

  // Sync features panel with SearchScreen's internal animation timing
  useEffect(() => {
    if (appState !== 'search') return
    const FEAT1_MS = 2300   // Brunei selected as pickup
    const FEAT2_MS = 4500   // KSB selected, tracking shows
    setFeatIndex(0)
    setFeatProgress(0)
    const start = Date.now()
    let raf: number
    const tick = () => {
      const elapsed = Date.now() - start
      if (elapsed < FEAT1_MS) {
        setFeatIndex(0); setFeatProgress(elapsed / FEAT1_MS)
        raf = requestAnimationFrame(tick)
      } else if (elapsed < FEAT2_MS) {
        setFeatIndex(1); setFeatProgress((elapsed - FEAT1_MS) / (FEAT2_MS - FEAT1_MS))
        raf = requestAnimationFrame(tick)
      } else {
        setFeatIndex(2); setFeatProgress(1)
      }
    }
    raf = requestAnimationFrame(tick)
    return () => cancelAnimationFrame(raf)
  }, [appState])

  // Scroll: drives --p CSS var and fires home→splash once
  useEffect(() => {
    const stage = stageRef.current
    if (!stage) return

    let frame = 0
    const update = () => {
      frame = 0
      const rect = stage.getBoundingClientRect()
      const vp = window.innerHeight
      const scrollable = Math.max(1, rect.height - vp)
      const scrolled = Math.min(Math.max(-rect.top, 0), scrollable)
      const p = scrolled / scrollable
      stage.style.setProperty('--p', p.toFixed(3))

      // mainP: 0→1 over the second 75% of the scroll range
      const mainP = Math.min(Math.max((p - 0.25) * 1.333, 0), 1)

      if (mainP >= 0.3 && appStateRef.current === 'home') {
        appStateRef.current = 'tapping'
        setAppState('tapping')
      }
    }

    const onScroll = () => { if (frame) return; frame = requestAnimationFrame(update) }
    update()
    window.addEventListener('scroll', onScroll, { passive: true })
    window.addEventListener('resize', update)
    return () => {
      if (frame) cancelAnimationFrame(frame)
      window.removeEventListener('scroll', onScroll)
      window.removeEventListener('resize', update)
    }
  }, [])

  return (
    <div className="sdi-stage" ref={stageRef}>
      <div className="sdi-sticky">

        {/* ── Backgrounds ── */}
        <div className="sdi-bg-base" />
        <div className="sdi-bg-green" />

        {/* ── Hero shadow overlay ── */}
        <div className="sdi-hero-shadow">
          <img src={HeroShadow} alt="" aria-hidden="true" />
        </div>

        {/* ── Section 1: hero content ── */}
        <div className="sdi-s1">
          <section className='flex items-center gap-3'>
            <figure className='w-16 h-16 p-2.5 bg-white rounded-[400px] shadow-[0px_16px_32px_-4px_rgba(12,12,13,0.10)] inline-flex justify-center items-center'>
              <img src={KNUSTCrest} alt="KNUST" className='w-50' />
            </figure>
            <figure className='w-16 h-16 p-2.5 bg-white rounded-[400px] shadow-[0px_16px_32px_-4px_rgba(12,12,13,0.10)] inline-flex justify-center items-center'>
              <img src={UGCrest} alt="UG" className='w-50' />
            </figure>
            <figure className='w-16 h-16 p-2.5 bg-white rounded-[400px] shadow-[0px_16px_32px_-4px_rgba(12,12,13,0.10)] inline-flex justify-center items-center'>
              <img src={UCCCrest} alt="UCC" className='w-50' />
            </figure>
          </section>

          <section className='flex flex-col gap-1 items-center py-2'>
            <h1 className="sdi-title">Real-Time Campus Mobility</h1>
            <p className="sdi-subtitle">
              A real-time shuttle tracking system designed to help students
              see bus locations, understand routes, and receive arrival alerts.
            </p>
          </section>

          <RouteCard />
        </div>

        {/* ── Phone: rises from bottom, screen syncs with appState ── */}
        <div className="sdi-phone-wrap">
          <div className="sdi-phone-float">
            <PhoneMockup appState={appState} />
          </div>
        </div>

        {/* ── Section 2: left copy ── */}
        <div className="sdi-s2-left">
          <h2 className="sdi-s2-title">
            Track Anywhere<br />Stay Updated.
          </h2>
          <p className="sdi-s2-body">
            Product thinking, interface design, and real-time engineering
            working together to solve transport uncertainty on campus.
          </p>
        </div>

        {/* ── Section 2: right — feature stepper with sliding highlight ── */}
        <div className="sdi-s2-right">
          <div className="sdi-features">

            {/* Sliding background pill */}
            <div ref={pillRef} className="sdi-feat-pill" style={{ opacity: 0 }} />

            {features.map(({ Icon, bg, title, desc }, i) => {
              const isActive = featIndex === i
              const isDone = featIndex > i
              return (
                <div
                  key={title}
                  ref={el => { itemRefs.current[i] = el }}
                  className={`sdi-feature${isActive ? ' sdi-feature--active' : ''}${isDone ? ' sdi-feature--done' : ''}`}
                >
                  <div className="sdi-feature-icon" style={{ background: isDone ? 'rgba(255,255,255,0.25)' : bg, borderRadius: 10 }}>
                    {isDone
                      ? <svg width="18" height="18" viewBox="0 0 24 24" fill="white"><path d="M9 16.17L4.83 12l-1.42 1.41L9 19 21 7l-1.41-1.41z" /></svg>
                      : <Icon />
                    }
                  </div>
                  <div className="sdi-feature-body">
                    <p className="sdi-feature-title">{title}</p>
                    <p className="sdi-feature-desc">{desc}</p>
                    {isActive && (
                      <div className="sdi-feat-bar">
                        <div className="sdi-feat-bar-fill" style={{ width: `${featProgress * 100}%` }} />
                      </div>
                    )}
                  </div>
                </div>
              )
            })}
          </div>
        </div>

      </div>
    </div>
  )
}

