function ProblemSection() {
  const stageRef = useRef<HTMLDivElement | null>(null)
  const innerRef = useRef<HTMLDivElement | null>(null)
  const paraRefs = useRef<(HTMLParagraphElement | null)[]>([])
  const prevIdx  = useRef(0)
  const [activeIndex, setActiveIndex] = useState(0)

  // Center active paragraph vertically — called from scroll handler and resize
  const focusPara = (idx: number) => {
    const inner = innerRef.current
    const para = paraRefs.current[idx]
    if (!inner || !para) return
    inner.style.transform = `translateY(${-(para.offsetTop + para.offsetHeight / 2)}px)`
  }

  // Position para 0 before first paint so there's no jump (mount-only)
  // eslint-disable-next-line react-hooks/exhaustive-deps
  useLayoutEffect(() => { focusPara(0) }, [])

  useEffect(() => {
    const stage = stageRef.current
    if (!stage) return

    let frame = 0
    const update = () => {
      frame = 0
      const rect = stage.getBoundingClientRect()
      const vp = window.innerHeight
      const scrollable = Math.max(1, rect.height - vp)
      const scrolled = Math.min(Math.max(-rect.top, 0), scrollable)
      const p = scrolled / scrollable

      // Drive island ring + visibility — no React re-render
      document.documentElement.style.setProperty('--island-p', p.toFixed(3))
      document.documentElement.style.setProperty('--island-visible', '1')

      const n = problemParagraphs.length
      const newIdx = Math.min(Math.floor(p * n), n - 1)
      if (newIdx !== prevIdx.current) {
        prevIdx.current = newIdx
        setActiveIndex(newIdx)
        focusPara(newIdx)
      }

    }

    const onScroll = () => { if (frame) return; frame = requestAnimationFrame(update) }
    const onResize = () => focusPara(prevIdx.current)
    update()
    window.addEventListener('scroll', onScroll, { passive: true })
    window.addEventListener('resize', onResize)
    return () => {
      if (frame) cancelAnimationFrame(frame)
      window.removeEventListener('scroll', onScroll)
      window.removeEventListener('resize', onResize)
      document.documentElement.style.setProperty('--island-p', '0')
      document.documentElement.style.setProperty('--island-visible', '0')
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  return (
    <div className="sdi-problem-stage" ref={stageRef}>
      <div className="sdi-problem-sticky">
        <div className="sdi-problem-inner" ref={innerRef}>
          {problemParagraphs.map((text, i) => (
            <p
              key={i}
              ref={el => { paraRefs.current[i] = el }}
              className={`sdi-problem-para${activeIndex === i ? ' sdi-problem-para--active' : ''}`}
            >
              {text}
            </p>
          ))}
        </div>
      </div>
    </div>
  )
}

// ── Messages scroll-pin wrapper ───────────────────────────────────────────────
//
//  Behaviour:
//  1. When the user scrolls down and Messages is partially visible, a smooth
//     scroll snaps it to fill the whole viewport automatically.
//  2. Once full-screen, the section dwells for 2×BUFFER scroll before the
//     sticky releases and the page continues to FlowSection.

function MessagesPinWrapper() {
  const outerRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    const outer = outerRef.current
    if (!outer) return

    // ~2 mouse-wheel clicks before leaving the section
    const BUFFER = 300

    // Outer height = viewport + entrance-buffer + exit-buffer
    const setHeight = () => {
      outer.style.height = `${window.innerHeight + 2 * BUFFER}px`
    }

    // Snap Messages to full screen when the user has scrolled it
    // more than 40 px into view (scrolling downward only).
    let lastY    = window.scrollY
    let snapLock = false

    const onScroll = () => {
      const y   = window.scrollY
      const dir = y > lastY ? 'down' : 'up'
      lastY = y

      if (snapLock || dir !== 'down') return

      const rect  = outer.getBoundingClientRect()
      const viewH = window.innerHeight

      // Trigger when Messages is partially entering from the bottom
      // (its top is between 40px and 65% of the viewport height)
      if (rect.top > 40 && rect.top < viewH * 0.65) {
        snapLock = true
        window.scrollTo({ top: y + rect.top, behavior: 'smooth' })
        // Release lock after scroll animation completes
        setTimeout(() => { snapLock = false }, 1200)
      }
    }

    setHeight()
    const ro = new ResizeObserver(setHeight)
    ro.observe(document.body)
    window.addEventListener('scroll', onScroll, { passive: true })
    window.addEventListener('resize', setHeight)

    return () => {
      ro.disconnect()
      window.removeEventListener('scroll', onScroll)
      window.removeEventListener('resize', setHeight)
    }
  }, [])

  return (
    <div ref={outerRef} style={{ position: 'relative' }}>
      {/* Sticky shell — Messages fills the viewport for the full dwell zone */}
      <div style={{ position: 'sticky', top: 0, height: '100vh', overflow: 'hidden' }}>
        <MessagesPage inline onBack={() => {}} />
      </div>
    </div>
  )
}

// ── Page ──────────────────────────────────────────────────────────────────────

const TAB_ORDER: Tab[] = ['product', 'design', 'engineering']

export default function ShuttleDetailPage({ onBack, onNext }: { onBack: () => void; onNext?: () => void }) {
  const [activeTab, setActiveTab] = useState<Tab>('product')
  const [tabKey,    setTabKey]    = useState(0)
  const [tabDir,    setTabDir]    = useState<'forward' | 'backward'>('forward')
  const flowRef      = useRef<HTMLDivElement>(null)
  const pendingLanding = useRef<TabLanding>('top')

  const scrollCurrentTabIntoView = (tab: Tab, landing: TabLanding) => {
    if (tab === 'product') {
      if (landing === 'flow') {
        flowRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' })
        return
      }
      window.scrollTo({ top: 0, behavior: 'smooth' })
      return
    }

    if (tab === 'design') {
      if (landing === 'end') {
        window.scrollTo({ top: document.documentElement.scrollHeight, behavior: 'smooth' })
        return
      }
      window.scrollTo({ top: 200, behavior: 'smooth' })
      return
    }

    window.scrollTo({ top: 0, behavior: 'smooth' })
  }

  const resolveLanding = (targetTab: Tab, currentTab: Tab, requestedLanding?: TabLanding): TabLanding => {
    if (requestedLanding) return requestedLanding
    if (targetTab === 'product' && currentTab !== 'product') return 'flow'
    if (targetTab === 'design' && currentTab === 'engineering') return 'end'
    return 'top'
  }

  const handleTabChange = (tab: Tab, opts?: { landing?: TabLanding }) => {
    const landing = resolveLanding(tab, activeTab, opts?.landing)
    if (tab === activeTab) {
      scrollCurrentTabIntoView(tab, landing)
      return
    }

    const dir = TAB_ORDER.indexOf(tab) > TAB_ORDER.indexOf(activeTab) ? 'forward' : 'backward'
    setTabDir(dir)
    setTabKey(k => k + 1)
    setActiveTab(tab)
    pendingLanding.current = landing
  }

  useLayoutEffect(() => {
    if (activeTab === 'product' && pendingLanding.current === 'flow') {
      pendingLanding.current = 'top'
      requestAnimationFrame(() => requestAnimationFrame(() => {
        flowRef.current?.scrollIntoView({ behavior: 'instant' })
      }))
      return
    }

    if (activeTab === 'engineering') {
      window.scrollTo({ top: 0, behavior: 'instant' as ScrollBehavior })
      return
    }

    if (activeTab === 'product') {
      window.scrollTo({ top: 0, behavior: 'instant' as ScrollBehavior })
    }
  }, [activeTab, tabKey])

  const designEntryPoint: DesignEntryPoint = pendingLanding.current === 'end' ? 'end' : 'hero'

  return (
    <div className="sdi-page">
      <DynamicIsland />
      <div key={tabKey} className={`sdi-tab-anim sdi-tab-anim--${tabDir}`}>
        {activeTab === 'product' && (
          <>
            <ProductView />
            <ProblemSection />
            <MessagesPinWrapper />
            <div ref={flowRef}>
              <FlowSection onComplete={() => handleTabChange('design')} />
            </div>
          </>
        )}
        {activeTab === 'design' && (
          <DesignSection
            entryPoint={designEntryPoint}
            onScrollUpAtTop={() => handleTabChange('product', { landing: 'flow' })}
            onScrollDownAtBottom={() => handleTabChange('engineering')}
          />
        )}
        {activeTab === 'engineering' && <EngineeringSection onScrollUpAtTop={() => handleTabChange('design', { landing: 'end' })} />}
      </div>
      <CaseStudyNavbar
        activeTab={activeTab}
        onTabChange={handleTabChange}
        onBack={onBack}
        onNext={onNext}
      />
    </div>
  )
}
